// Founder signal ingest. Lane hive-os. Register to Scorpion; do not rebuild day-plan here.
const body = $json.body || $json;

const signal = {
  signalId: body.signalId || body.id || body.correlationId || `sig_${Date.now()}`,
  signalType: body.signalType || body.type || 'founder-signal',
  source: body.source || 'ecosystem-router',
  title: body.title || body.subject || 'Untitled Signal',
  content: body.content || body.message || body.text || body.description || '',
  priority: body.priority || 'normal',
  metadata: body.metadata || {},
  receivedAt: new Date().toISOString(),
  lane: body.lane || 'hive-os'
};

return [{
  json: {
    ...signal,
    registerPayload: {
      correlationId: signal.signalId,
      jobType: 'hive.founder_signal.ingested',
      goal: signal.title,
      source: signal.source,
      status: 'done',
      registerTo: 'scorpion',
      summary: signal.content || signal.title,
      metadata: {
        lane: signal.lane,
        signalType: signal.signalType,
        telegramRequired: 'false'
      }
    }
  }
}];
